            $jabatan = $e[2];

            if ($jabatan) {
                if (!isset($posCache[$jabatan])) {
                    $pos = Position::where('nama_jabatan', $jabatan)->first();
                    if (!$pos) {
                        $pos = Position::create(['nama_jabatan' => $jabatan, 'department_id' => $defaultDept->id]);
                    }
                    $posCache[$jabatan] = $pos->id;
                }
                $posId = $posCache[$jabatan];
            } else {
                $posId = $defaultPos->id;
            }

            Employee::create([
                'nama_lengkap'  => $e[0],
                'id_badge'      => $e[1] ?? 'AKM-' . uniqid() . '',
                'no_ktp'        => $e[3],
